import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        t_str = next(iterator)
        T = int(t_str)
    except StopIteration:
        return

    output = []

    for _ in range(T):
        try:
            n_str = next(iterator)
            n = int(n_str)
            a = []
            for _ in range(n):
                a.append(int(next(iterator)))
        except StopIteration:
            break

        if n == 0:
            output.append("YES")
            continue

        b = sorted(a)

        possible = True
        for i in range(n):
            if abs(a[i] - b[i]) > 0:
                pass

            if a[i] != b[i]:
                if i + 1 < n and a[i] == b[i+1] and a[i+1] == b[i]:
                    continue
                elif i - 1 >= 0 and a[i] == b[i-1] and a[i-1] == b[i]:
                    continue
                else:
                    possible = False
                    break

        if possible:
            output.append("YES")
        else:
            output.append("NO")

    sys.stdout.write('\n'.join(output) + '\n')

if __name__ == "__main__":
    solve()
